function holdsCurrent(item: NavRoot, currentNodeId: string) {
  if (item.id === currentNodeId) return true;
  return (item.children ?? []).some(
    (child) => child.id === currentNodeId || (child.children ?? []).some((leaf) => leaf.id === currentNodeId)
  );
}

