const [tags, setTags] = React.useState(["Liderazgo", "Ventas", "Bogotá", "Q3 2026"]);
const remove = (label: string) => setTags((prev) => prev.filter((t) => t !== label));

{tags.map((label) => (
  <Tag key={label} label={label} tone="info" removable onRemove={() => remove(label)} />
))}
